import com.android.tools.smali.dexlib2.*;
import com.android.tools.smali.dexlib2.iface.instruction.*;
public class InspectCallback{public static void main(String[]a)throws Exception{var c=DexFileFactory.loadDexContainer(new java.io.File(a[0]),Opcodes.forDexVersion(39));for(var n:c.getDexEntryNames())for(var cl:c.getEntry(n).getDexFile().getClasses())if(cl.getType().endsWith("/APSClientCallback;"))for(var m:cl.getMethods())if(m.getName().equals("onTransact")){System.out.println("registers="+m.getImplementation().getRegisterCount()+" params="+m.getParameterTypes());int pc=0;for(var i:m.getImplementation().getInstructions()){if(pc<14)System.out.println(pc+" "+i.getOpcode()+" "+(i instanceof OneRegisterInstruction r?r.getRegisterA():"")+" "+(i instanceof ReferenceInstruction r?r.getReference():""));pc+=i.getCodeUnits();}}}}
